<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$active=array_filter($rules,static fn($r)=>(int)$r['active']===1);?>
<div class="space-y-6"><header><h1 class="text-3xl font-bold">Protección de la base de datos</h1><p class="text-slate-400 mt-1">MariaDB permanece cerrada al exterior. Solo las IP exactas de balanceadores registrados pueden autorizarse.</p></header><section class="grid md:grid-cols-3 gap-4"><div class="bg-emerald-950/40 border border-emerald-800 rounded-xl p-5"><span class="text-sm text-emerald-300">Política</span><strong class="block text-xl mt-1">Denegar por defecto</strong></div><div class="bg-slate-900 border border-slate-800 rounded-xl p-5"><span class="text-sm text-slate-400">IP autorizadas</span><strong class="block text-2xl mt-1"><?=count($active)?></strong></div><div class="bg-slate-900 border border-slate-800 rounded-xl p-5"><span class="text-sm text-slate-400">Acceso local</span><strong class="block text-xl text-emerald-400 mt-1">Siempre permitido</strong></div></section><aside class="border border-amber-800 bg-amber-950/20 rounded-xl p-4 text-sm text-amber-200"><strong>Importante:</strong> los balanceadores OrionX normalmente usan la API firmada y no necesitan MySQL. Autoriza 3306 solamente para una integración que realmente lo requiera. Los cambios no se activan hasta pulsar “Aplicar reglas”.</aside>
<section class="bg-slate-900 border border-slate-800 rounded-xl p-5"><h2 class="text-xl font-bold">Autorizar balanceador</h2><form method="post" action="/security/database/add" class="grid md:grid-cols-3 gap-3 mt-4"><?=$csrf->field()?><select required name="server_id" class="bg-slate-800 p-2 rounded"><option value="">Selecciona un balanceador</option><?php foreach($servers as $s):?><option value="<?=$s['id']?>"><?=$e($s['name'])?> · pública <?=$e($s['public_ip']?:'—')?> · privada <?=$e($s['private_ip']?:'—')?></option><?php endforeach?></select><select name="ip_kind" class="bg-slate-800 p-2 rounded"><option value="private">IP privada</option><option value="public">IP pública</option></select><button class="bg-cyan-700 rounded p-2">Añadir a lista permitida</button></form></section>
<section><div class="flex justify-between items-end mb-3"><div><h2 class="text-xl font-bold">Lista permitida</h2><p class="text-sm text-slate-400">No se aceptan rangos CIDR: solamente una IP exacta por regla.</p></div><form method="post" action="/security/database/apply" onsubmit="return confirm('Esto modificará UFW, la escucha de MariaDB y reiniciará MariaDB. ¿Aplicar ahora?')"><?=$csrf->field()?><button class="bg-red-700 px-4 py-2 rounded font-bold">Aplicar reglas</button></form></div><div class="overflow-x-auto border border-slate-800 rounded-xl"><table class="w-full text-sm"><thead class="bg-slate-900 text-slate-400"><tr><th class="p-3 text-left">Balanceador</th><th>IP</th><th>Tipo</th><th>Servidor</th><th>Regla</th><th class="p-3 text-right">Acción</th></tr></thead><tbody><?php foreach($rules as $r):?><tr class="border-t border-slate-800"><td class="p-3"><?=$e($r['server_name'])?></td><td class="text-center font-mono"><?=$e($r['ip'])?></td><td class="text-center"><?=$e($r['ip_kind'])?></td><td class="text-center"><?=$e($r['server_status'])?></td><td class="text-center <?=$r['active']?'text-emerald-400':'text-slate-500'?>"><?=$r['active']?'Permitida':'Desactivada'?></td><td class="p-3 text-right"><?php if($r['active']):?><form method="post" action="/security/database/remove" onsubmit="return confirm('¿Retirar esta IP? Después deberás aplicar las reglas.')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="bg-slate-700 px-3 py-1 rounded">Retirar</button></form><?php endif?></td></tr><?php endforeach?><?php if(!$rules):?><tr><td colspan="6" class="p-10 text-center text-slate-500">No hay acceso remoto autorizado. MariaDB permanece en localhost.</td></tr><?php endif?></tbody></table></div></section><section><h2 class="text-xl font-bold mb-3">Historial</h2><div class="space-y-2"><?php foreach($runs as $run):?><div class="bg-slate-900 border <?=$run['status']==='failed'?'border-red-800':'border-slate-800'?> rounded-lg p-3 flex justify-between"><span>#<?=$run['id']?> · <?=$e($run['created_at'])?> · <?=$run['rules_count']?> reglas · <?=$e($run['actor']?:'Sistema')?></span><span class="<?=$run['status']==='completed'?'text-emerald-400':($run['status']==='failed'?'text-red-400':'text-amber-400')?>"><?=$e($run['status'])?></span></div><?php endforeach?></div></section></div>
